# Title: Regression: The title of create test case button should be +Test Case instead of +New Test Case
# Feature: Regression / Default
import pytest

pytestmark = pytest.mark.asyncio


async def test_regression_the_title_of_create_test_case_button_should_be_te(page, base_url):
    target_url = f"{base_url.rstrip('/')}/workspace/9bfc7400-2e1a-4c83-8638-285418ab0564/project/e011c0f0-e3e3-4497-adaf-4687ca17773d/tests"
    await page.goto(target_url)

    try:
        await page.wait_for_load_state('networkidle', timeout=8000)
    except:
        pass

    create_test_button = page.get_by_role('button', name='+Test Case')
    
    await create_test_button.wait_for(state='visible', timeout=8000)
    
    assert await create_test_button.is_visible(), 'The "+Test Case" button should be visible on the page.'
    
    # Verify that the button with the old text "+New Test Case" does not exist
    old_button = page.get_by_role('button', name='+New Test Case')
    assert await old_button.count() == 0, 'The button should not be labeled "+New Test Case".'
